    function initializeOrRefreshPanel(dataFromAI) {
        parsedPanelData = parseAIDataToStructuredObject(dataFromAI);
        currentBPoints = parsedPanelData.装逼值 || 0;
        currentHostTitle = parsedPanelData.称号 || "";
        populateTextContent('hostNameElem', parsedPanelData.姓名 + (parsedPanelData.别名 && parsedPanelData.别名 !== parsedPanelData.姓名 ? ' ('+parsedPanelData.别名+')' : ''));
        populateTextContent('hostRealmElem', parsedPanelData.境界);
        populateTextContent('hostTitleElem', parsedPanelData.称号);
        populateTextContent('hostJobElem', parsedPanelData.职业);
        populateTextContent('bPointValueElem', formatNumber(currentBPoints));
        populateTextContent('systemSloganElem', "\"" + (parsedPanelData.系统标语 || '装逼如风...') + "\"");
        updateProgressBar('healthBarElem', parsedPanelData.生命百分比);
        updateProgressBar('staminaBarElem', parsedPanelData.体力百分比);
        updateProgressBar('desireBarElem', parsedPanelData.欲望百分比);
        updateProgressBar('expBarElem', parsedPanelData.经验百分比);
        populateShop();
        populateGifts();
        populateSkills();
        populateTasks();
        populateInventory();
        populateFunctions();
        const activeTabButton = document.querySelector('.tab-button.active');
        if (activeTabButton) {
            openTab({ currentTarget: activeTabButton }, activeTabButton.getAttribute('onclick').match(/'([^']+)'/)[1]);
        } else {
            const firstTab = document.querySelector('.tab-button');
            if (firstTab) {
                firstTab.classList.add('active');
                openTab({ currentTarget: firstTab }, firstTab.getAttribute('onclick').match(/'([^']+)'/)[1]);
            }
        }
        updatePendingActionsDisplay();
        consoleLog("Panel UI refreshed using parsed AI data.");
    }

    function updatePendingActionsDisplay() {
        const listElement = document.getElementById('pendingActionsList');
        const countElement = document.getElementById('pendingActionsCount');
        if (!listElement || !countElement) return;
        countElement.textContent = pendingActions.length;
        listElement.innerHTML = '';
        pendingActions.forEach(actionObj => {
            const listItem = document.createElement('li');
            listItem.textContent = actionObj.text.length > 70 ? actionObj.text.substring(0, 67) + "..." : actionObj.text;
            listItem.title = actionObj.text;
            listElement.appendChild(listItem);
        });
    }
    function addPendingAction(actionObject) {
        pendingActions.push(actionObject);
        updatePendingActionsDisplay();
        consoleLog("Action added to pending: " + actionObject.text);
    }
    async function sendPendingActionsToInput() {
        if (pendingActions.length === 0) {
            consoleLog("No pending actions to send.");
            return;
        }
        const combinedActionsText = pendingActions.map(action => action.text).join('\n');
        if (typeof triggerSlash === 'function') {
            try {
                await triggerSlash("/setinput \"" + escapeForSetInput(combinedActionsText) + "\"");
                consoleLog(pendingActions.length + " actions prepared for user input.");
                pendingActions = [];
                updatePendingActionsDisplay();
            } catch (e) {
                consoleLog("ERROR filling combined actions: " + (e.message || e));
                showSystemModal("面板错误", "填充操作到输入框失败！", "error");
            }
        } else { consoleLog("WARN: triggerSlash not available."); }
    }
    async function clearPendingActions() {
        if (pendingActions.length === 0) { consoleLog("Pending actions list already empty."); return; }
        let refundedBPoints = 0;
        pendingActions.forEach(action => {
            if (action.cost && action.cost > 0 && action.costType === 'bpoints') {
                currentBPoints += action.cost;
                refundedBPoints += action.cost;
            }
        });
        pendingActions = [];
        updatePendingActionsDisplay();
        if (refundedBPoints > 0) {
            populateTextContent('bPointValueElem', formatNumber(currentBPoints));
            consoleLog("Pending actions cleared. Refunded " + formatNumber(refundedBPoints) + " BPoints. Current BPoints: " + formatNumber(currentBPoints));
        } else {
            consoleLog("Pending actions cleared.");
        }
    }
    function openTab(evt, tabName) {
        let i, tabcontent, tablinks;
        tabcontent = document.getElementsByClassName("tab-content");
        for (i = 0; i < tabcontent.length; i++) { tabcontent[i].style.display = "none"; tabcontent[i].classList.remove("active"); }
        tablinks = document.getElementsByClassName("tab-button");
        for (i = 0; i < tablinks.length; i++) { tablinks[i].classList.remove("active"); }
        const currentTabContent = document.getElementById(tabName);
        if (currentTabContent) { currentTabContent.style.display = "block"; currentTabContent.classList.add("active"); }
        if (evt && evt.currentTarget) { evt.currentTarget.classList.add("active"); }
        else {
            const buttons = document.querySelectorAll('.tab-button');
            buttons.forEach(button => { if (button.getAttribute('onclick').includes("'" + tabName + "'")) { button.classList.add('active'); } });
        }
    }

    function showSystemModal(title, message, severity = "info") {
        const modalOverlay = document.getElementById('systemModal');
        const modalTitleElem = document.getElementById('systemModalTitle');
        const modalMessageElem = document.getElementById('systemModalMessage');
        const modalContentElem = modalOverlay.querySelector('.modal-content');

        if (!modalOverlay || !modalTitleElem || !modalMessageElem || !modalContentElem) {
            consoleLog("ERROR: System modal elements not found. Fallback to console.");
            console.error("Modal Fallback: Title: " + title + ", Message: " + message + ", Severity: " + severity);
            return;
        }
        modalTitleElem.textContent = title;
        modalMessageElem.textContent = message.replace(/\\n/g, '\n');
        modalContentElem.classList.remove('error', 'warning', 'info');
        if (severity) { modalContentElem.classList.add(severity.toLowerCase()); }
        modalOverlay.style.display = 'flex';
    }

    function hideSystemModal() {
        const modalOverlay = document.getElementById('systemModal');
        if (modalOverlay) { modalOverlay.style.display = 'none'; }
    }

    async function handleAction(type, itemName, itemData) {
        consoleLog("Action: " + type + ", Item: " + itemName + ", ItemData: " + JSON.stringify(itemData));
        let actionDescription = "";
        let cost = 0;
        let actionObject = { text: "", cost: 0, costType: "" };
        let rawErrorMessage = "";
        let displayErrorMessage = "";

        if (type === 'buy') {
            cost = parseInt(itemData) || 0; // itemData here is the price
            if (currentBPoints >= cost) {
                currentBPoints -= cost;
                populateTextContent('bPointValueElem', formatNumber(currentBPoints));
                actionDescription = "兑换【" + itemName + "】";
                actionObject = { text: actionDescription, cost: cost, costType: 'bpoints' };
                addPendingAction(actionObject);
            } else {
                rawErrorMessage = "装逼值不足 (" + formatNumber(currentBPoints) + "/" + formatNumber(cost) + ")，无法兑换【" + itemName + "】！";
                displayErrorMessage = rawErrorMessage; if (itemName.length > 12) { displayErrorMessage = "装逼值不足 (" + formatNumber(currentBPoints) + "/" + formatNumber(cost) + ")，\n无法兑换：【" + itemName + "】！"; }
                showSystemModal("兑换失败", displayErrorMessage, "error"); return;
            }
        } else if (type === 'claim_gift') { // itemData is the gift object
            if (itemData && itemData.状态 === '可领取' && !itemData.已领取) {
                const giftContents = itemData.内容 || "一些神秘奖励";
                actionDescription = "我开启了礼包【" + (itemData.名称 || itemName) + "】。获得了：" + giftContents;
                actionObject = { text: actionDescription, cost: 0 }; addPendingAction(actionObject);
            } else {
                rawErrorMessage = "礼盒【" + (itemData.名称 || itemName) + "】当前无法开启！";
                displayErrorMessage = rawErrorMessage; if ((itemData.名称 || itemName).length > 12) { displayErrorMessage = "礼盒：【" + (itemData.名称 || itemName) + "】\n当前无法开启！"; }
                showSystemModal("操作失败", displayErrorMessage, "error"); return;
            }
        } else if (type === 'manage_skill') { // itemData is the skill object
            actionDescription = (itemData?.按钮文字 || "操作") + "技能【" + itemName + "】";
            actionObject = { text: actionDescription, cost: 0 }; addPendingAction(actionObject);
        } else if (type === 'manage_task') { // itemData is the task object
            actionDescription = (itemData?.按钮文字 || "操作") + "【" + itemName + "】";
            actionObject = { text: actionDescription, cost: 0 }; addPendingAction(actionObject);
        } else if (type === 'use_item') { // itemData is the item object from inventory
            actionDescription = "使用物品【" + (itemData?.名称 || itemName) + "】";
            actionObject = { text: actionDescription, cost: 0 }; addPendingAction(actionObject);
        } else if (type === 'use_function') { // itemData is the function object
            cost = parseInt(itemData?.消耗) || 0;
            if (itemData?.禁用) {
                rawErrorMessage = "功能【" + (itemData.名称 || itemName) + "】当前不可用。";
                showSystemModal("功能禁用", rawErrorMessage, "warning"); return;
            }
            if (cost > 0 && currentBPoints < cost) {
                rawErrorMessage = "装逼值不足 (" + formatNumber(currentBPoints) + "/" + formatNumber(cost) + ")，无法启动【" + (itemData.名称 || itemName) + "】！";
                displayErrorMessage = rawErrorMessage; if ((itemData.名称 || itemName).length > 10) { displayErrorMessage = "装逼值不足 (" + formatNumber(currentBPoints) + "/" + formatNumber(cost) + ")，\n无法启动：【" + (itemData.名称 || itemName) + "】！"; }
                showSystemModal("功能失败", displayErrorMessage, "error"); return;
            }
            if (cost > 0) { currentBPoints -= cost; populateTextContent('bPointValueElem', formatNumber(currentBPoints)); }
            actionDescription = "我使用了系统辅助功能【" + (itemData.名称 || itemName) + "】" + (cost > 0 ? "，消耗了 " + formatNumber(cost) + " 装逼值" : '') + "。";
            actionObject = { text: actionDescription, cost: cost, costType: 'bpoints' }; addPendingAction(actionObject);
        } else {
            consoleLog("WARN: Unknown action type: " + type); return;
        }
    }

    function modifyCapturedDataContent(capturedContent, replacementText) {
        let occurrence = 0;
        const stringToFind = String.fromCharCode(36) + "1";
        const regexToFind = new RegExp(stringToFind.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), "g");
        const modifiedContent = capturedContent.replace(regexToFind, (match) => {
            occurrence++;
            if (occurrence === 2) {
                return replacementText;
            }
            return match;
        });
        return modifiedContent;
    }

    function processAndRenderPanelFromAIData(aiDataString) {
        if (typeof aiDataString !== 'string' || aiDataString.trim() === "") {
            consoleLog("WARN: AI data string is empty or invalid for panel rendering.");
            initializeOrRefreshPanel("");
            return;
        }
        initializeOrRefreshPanel(aiDataString);
    }

    const textToReplaceSecondOccurrenceInAIData = "";
    let rawAIDataFromCaptureGroup = `$1`;
    let processedAIData = modifyCapturedDataContent(rawAIDataFromCaptureGroup, textToReplaceSecondOccurrenceInAIData);
    processAndRenderPanelFromAIData(processedAIData);

