   .modal-overlay {
    position: fixed; top: 0; left: 0; width: 100%; height: 100%;
    background-color: rgba(0, 0, 0, 0.7); display: none;
    justify-content: center; align-items: center; z-index: 1001; padding: 1rem;
   }
   .modal-content {
    background-color: #0a192f; border: 2px solid #64ffda; border-radius: 10px;
    padding: 1.5rem; box-shadow: 0 5px 25px rgba(0,0,0,0.5);
    width: auto; max-width: 90%; min-width: 300px; max-height: 80vh; overflow-y: auto;
    position: relative; color: #ccd6f6; animation: modalFadeIn 0.3s ease-out;
   }
   @keyframes modalFadeIn { from { opacity: 0; transform: translateY(-30px) scale(0.95); } to { opacity: 1; transform: translateY(0) scale(1); } }
