   .modal-body p { margin: 0; line-height: 1.7; font-size: 1em; white-space: pre-wrap; overflow-wrap: break-word; }
   .modal-content.error .modal-header { border-left: 6px solid #f87171; padding-left: 0.75rem; }
   .modal-content.error .modal-title-text { color: #f87171; }
