   @media (max-width: 850px) {
       .main-info-grid { grid-template-columns: 1fr; }
       .b-point-display-container { position: static; margin-bottom:1rem; text-align:center;}
   }
   @media (max-width: 768px) {
     .system-title { font-size: 2em; }
     .tabs { flex-direction: column; }
     .tab-button { margin: 0.3rem 0; border-radius: 8px; }
