     .tab-content .item-name, .tab-content .item-detail { min-width: 100%; margin-bottom: 5px; margin-right: 0;}
     .tab-content .item-action { margin-left: 0; width: 100%; text-align: right; margin-top: 5px;}
     .modal-content { max-width: 95%; }
