     .info-column h3 { font-size: 1.1em; }
     .info-column p, .info-column div.status-item, .tab-content li, .pending-actions-list li { font-size: 0.9em; }
     .pending-actions-buttons { flex-direction: column; gap: 0.5rem; }
     .b-point-display-container .b-point-value { font-size: 1.2em; }
     .modal-title-text { font-size: 1.2em;}
     .modal-body p { font-size: 0.95em; }
   }
 </style>
 </head>
 <body>
  <div class="container">
    <div class="b-point-display-container">
        <span class="b-point-label">装逼值:</span> <span id="bPointValueElem" class="b-point-value">0</span>
    </div>

    <div class="system-panel">
      <h1 class="system-title">最强装逼打脸系统</h1>

      <div class="main-info-grid">
        <div class="info-column" id="host-primary-info">
            <h3>宿主档案</h3>
            <p><span class="info-label">姓名:</span> <span id="hostNameElem" class="value">-</span></p>
            <p><span class="info-label">境界:</span> <span id="hostRealmElem" class="value highlight">-</span></p>
            <p><span class="info-label">称号:</span> <span id="hostTitleElem" class="value">-</span></p>
            <p><span class="info-label">职业:</span> <span id="hostJobElem" class="value">-</span></p>
        </div>
        <div class="info-column" id="host-status-bars">
            <h3>状态面板</h3>
            <div class="status-item">
                <span class="info-label">生命值:</span>
                <div class="progress-bar-container">
                    <div class="progress-bar health" id="healthBarElem">0%</div>
                </div>
            </div>
            <div class="status-item">
                <span class="info-label">体力值:</span>
                <div class="progress-bar-container">
                    <div class="progress-bar stamina" id="staminaBarElem">0%</div>
                </div>
            </div>
            <div class="status-item">
                <span class="info-label">欲望值:</span>
                <div class="progress-bar-container">
                    <div class="progress-bar desire" id="desireBarElem">0%</div>
                </div>
            </div>
            <div class="status-item">
                <span class="info-label">经验值:</span>
                <div class="progress-bar-container">
                    <div class="progress-bar exp" id="expBarElem">0%</div>
                </div>
            </div>
        </div>
      </div>

      <div class="tabs">
        <button class="tab-button active" onclick="openTab(event, 'shop')">系统商城</button>
        <button class="tab-button" onclick="openTab(event, 'gifts')">礼包系统</button>
        <button class="tab-button" onclick="openTab(event, 'skills')">功法技能</button>
        <button class="tab-button" onclick="openTab(event, 'tasks')">系统任务</button>
        <button class="tab-button" onclick="openTab(event, 'inventory')">系统空间</button>
        <button class="tab-button" onclick="openTab(event, 'functions')">辅助功能</button>
      </div>

      <div id="shop" class="tab-content active">
        <h2>系统商城</h2>
        <ul id="shopListElem"><li><span class="item-name" style="text-align:center; display:block;">等待AI数据...</span></li></ul>
        <p id="shopDiscountInfoElem" style="font-size:0.8em; color:#8892b0; margin-top:1rem;"></p>
      </div>
      <div id="gifts" class="tab-content">
        <h2>礼包中心</h2>
        <ul id="giftListElem"><li><span class="item-name" style="text-align:center; display:block;">等待AI数据...</span></li></ul>
      </div>
      <div id="skills" class="tab-content">
        <h2>功法与技能</h2>
        <ul id="skillListElem"><li><span class="item-name" style="text-align:center; display:block;">等待AI数据...</span></li></ul>
      </div>
       <div id="tasks" class="tab-content">
        <h2>系统任务</h2>
        <div class="task-category">
            <h3>主线任务</h3>
            <ul id="taskListMain"><li><span class="item-name" style="text-align:center; display:block;">暂无主线任务</span></li></ul>
        </div>
        <div class="task-category">
            <h3>支线任务</h3>
            <ul id="taskListSide"><li><span class="item-name" style="text-align:center; display:block;">暂无支线任务</span></li></ul>
        </div>
        <div class="task-category">
            <h3>特殊任务</h3>
            <ul id="taskListSpecial"><li><span class="item-name" style="text-align:center; display:block;">暂无特殊任务</span></li></ul>
        </div>
      </div>
      <div id="inventory" class="tab-content">
        <h2>系统空间 (仓库)</h2>
        <p id="inventoryDescriptionElem" style="text-align:center; color:#a8b2d1; margin-top:2rem;">等待AI数据...</p>
        <ul id="inventoryListElem"></ul>
      </div>
      <div id="functions" class="tab-content">
        <h2>系统辅助功能</h2>
        <ul id="functionListElem"><li><span class="item-name" style="text-align:center; display:block;">等待AI数据...</span></li></ul>
      </div>

      <div class="pending-actions-container">
        <h3>待处理操作 (<span id="pendingActionsCount">0</span> 条)</h3>
        <ul id="pendingActionsList" class="pending-actions-list"></ul>
        <div class="pending-actions-buttons">
            <button onclick="sendPendingActionsToInput()">执行选中操作</button>
            <button id="clearPendingActionsBtn" onclick="clearPendingActions()">清除待选操作</button>
        </div>
      </div>

      <div class="footer-text-container">
        <p class="footer-text" id="systemSloganElem">"等待AI赋予系统灵魂..."</p>
      </div>
    </div>

    <div id="systemModal" class="modal-overlay">
        <div class="modal-content">
            <div class="modal-header">
                <h3 id="systemModalTitle" class="modal-title-text">提示</h3>
                <button class="modal-close-btn" onclick="hideSystemModal()">×</button>
            </div>
            <div class="modal-body">
                <p id="systemModalMessage"></p>
            </div>
        </div>
    </div>

  </div>

  <script>
    let currentBPoints = 0;
    let currentHostTitle = "";
    let pendingActions = [];
    let parsedPanelData = {};

    function consoleLog(message) { console.log("[SysPanel v1.5.3]: " + String(message)); }
    function formatNumber(num) { return String(num).replace(/(\d)(?=(\d{3})+(?!\d))/g, String.fromCharCode(36) + "1,"); }
    function escapeForSetInput(text) {
        if (typeof text !== 'string') text = String(text);
        return text.replace(/"/g, '\\"').replace(/'/g, "\\'").replace(/\n/g, '\\n');
    }

    function parseAIDataToStructuredObject(dataString) {
        const lines = dataString.trim().split('\n');
        const data = {
            姓名: "-", 别名: "-", 境界: "-", 称号: "-", 职业: "-",
            生命百分比: "0%", 体力百分比: "0%", 欲望百分比: "0%", 经验百分比: "0%",
            装逼值: 0, 系统标语: "系统初始化...", 商城折扣信息: "",
            商城物品列表: [], 礼包列表: [], 技能列表: [],
            主线任务列表: [], 支线任务列表: [], 特殊任务列表: [],
            库存描述: "空间空空如也。", 库存物品列表: [], 辅助功能列表: []
        };
        let currentListType = null;
        lines.forEach(line => {
            const parts = line.match(/^([^:]+):\s*(.*)$/);
            if (!parts) return;
            const key = parts[1].trim();
            const value = parts[2].trim();

            if (key.endsWith('数量')) {
                const listKeyPrefix = key.substring(0, key.indexOf('数量'));
                const listMap = {
                    "商城物品": "商城物品", "礼包": "礼包", "技能": "技能",
                    "主线任务": "主线任务", "支线任务": "支线任务", "特殊任务": "特殊任务",
                    "库存物品": "库存物品", "辅助功能": "辅助功能"
                };
                if (listMap[listKeyPrefix]) {
                    currentListType = listMap[listKeyPrefix];
                    const listDataKey = currentListType + "列表";
                    if (data.hasOwnProperty(listDataKey)) data[listDataKey] = [];
                } else { currentListType = null; }
                return;
            }

            if (currentListType) {
                const itemPrefix = currentListType + "_";
                if (key.startsWith(itemPrefix)) {
                    const itemKeyParts = key.substring(itemPrefix.length).split('_');
                    const itemIndex = parseInt(itemKeyParts[0]) - 1;
                    const itemPropName = itemKeyParts.slice(1).join('_');
                    const listDataKey = currentListType + "列表";
                    let targetList = data.hasOwnProperty(listDataKey) ? data[listDataKey] : null;

                    if (targetList) {
                        if (!targetList[itemIndex]) targetList[itemIndex] = {};
                        let currentItem = targetList[itemIndex];
                        if (itemPropName === "价格" || itemPropName === "消耗" || itemPropName === "数量") {
                            currentItem[itemPropName] = parseInt(value) || 0;
                        } else if (itemPropName === "已领取" || itemPropName === "禁用") {
                            currentItem[itemPropName] = value.toLowerCase() === 'true';
                        } else {
                            currentItem[itemPropName] = value;
                        }
                    }
                    return;
                }
            }
            switch (key) {
                case '姓名': data.姓名 = value; break;
                case '别名': data.别名 = value; break;
                case '境界': data.境界 = value; break;
                case '称号': data.称号 = value; break;
                case '职业': data.职业 = value; break;
                case '生命百分比': data.生命百分比 = value; break;
                case '体力百分比': data.体力百分比 = value; break;
                case '欲望百分比': data.欲望百分比 = value; break;
                case '经验百分比': data.经验百分比 = value; break;
                case '装逼值': data.装逼值 = parseInt(value) || 0; break;
                case '系统标语': data.系统标语 = value; break;
                case '商城折扣信息': data.商城折扣信息 = value; break;
                case '库存描述': data.库存描述 = value; break;
                default: break;
            }
        });
        consoleLog("Parsed AI Data Object:"); console.dir(data);
        return data;
    }

    function updateProgressBar(barElementId, percentageText) {
        const barElement = document.getElementById(barElementId);
        if (!barElement) return;
        let cleanPercentage = parseFloat(String(percentageText).replace('%',''));
        if (isNaN(cleanPercentage) || cleanPercentage < 0) cleanPercentage = 0;
        if (cleanPercentage > 100) cleanPercentage = 100;
        barElement.style.width = cleanPercentage + '%';
        barElement.textContent = cleanPercentage.toFixed(0) + '%';
    }

    function populateTextContent(elementId, text, defaultValue = "-") {
        const elem = document.getElementById(elementId);
        if (elem) elem.textContent = text || defaultValue;
    }

    function populateShop() {
        const listElem = document.getElementById('shopListElem');
        const discountElem = document.getElementById('shopDiscountInfoElem');
        listElem.innerHTML = '';
        if(discountElem) discountElem.textContent = parsedPanelData.商城折扣信息 || '* 温馨提示：部分稀有商品可能需要特殊条件解锁。';
        if (!parsedPanelData.商城物品列表 || parsedPanelData.商城物品列表.length === 0) {
            listElem.innerHTML = '<li><span class="item-name" style="text-align:center; display:block;">万界商城通讯受阻...</span></li>'; return;
        }
        const discountActive = currentHostTitle && currentHostTitle.includes("装逼犯");
        const discountRate = discountActive ? 0.9 : 1;
        parsedPanelData.商城物品列表.forEach(item => {
            const actualPrice = Math.floor((item.价格 || 0) * discountRate);
            let priceText = formatNumber(actualPrice) + " 装逼值";
            if (discountActive && (item.价格 || 0) !== actualPrice) {
                priceText = "<span style=\"text-decoration: line-through; color: #8892b0;\">" + formatNumber(item.价格 || 0) + "</span> " + formatNumber(actualPrice) + " 装逼值";
            }
            const li = document.createElement('li');
            const btn = document.createElement('button');
            btn.textContent = item.按钮文字 || '兑换';
            btn.onclick = () => handleAction('buy', item.名称, actualPrice);
            const nameSpan = document.createElement('span'); nameSpan.className = "item-name"; nameSpan.textContent = item.名称;
            const detailSpan = document.createElement('span'); detailSpan.className = "item-detail"; detailSpan.innerHTML = priceText;
            const actionSpan = document.createElement('span'); actionSpan.className = "item-action"; actionSpan.appendChild(btn);
            li.appendChild(nameSpan); li.appendChild(detailSpan); li.appendChild(actionSpan);
            listElem.appendChild(li);
        });
    }

    function populateGifts() {
        const listElem = document.getElementById('giftListElem');
        listElem.innerHTML = '';
        if (!parsedPanelData.礼包列表 || parsedPanelData.礼包列表.length === 0) {
            listElem.innerHTML = '<li><span class="item-name" style="text-align:center; display:block;">暂无待开启的次元礼盒。</span></li>'; return;
        }
        parsedPanelData.礼包列表.forEach(gift => {
            const li = document.createElement('li');
            let detailStyle = ''; if (gift.状态 === "可领取") detailStyle = 'color: #64ffda;'; else if (gift.状态 === "未解锁") detailStyle = 'color: #ff79c6;'; else if (gift.状态 === "已领取" || gift.状态 === "已开启") detailStyle = 'color: #4a5568;';
            let conditionText = gift.条件 ? " (" + gift.条件 + ")" : '';
            let buttonText = '查阅'; let buttonDisabled = true;
            if (gift.状态 === "可领取" && !gift.已领取) { buttonText = '开启'; buttonDisabled = false; }
            else if (gift.状态 === "已领取" || gift.状态 === "已开启" || gift.已领取) { buttonText = '已开启'; buttonDisabled = true; }
            else if (gift.状态 === "未解锁") { buttonText = '未达到'; buttonDisabled = true; }
            const displayName = gift.内容 ? gift.名称 + " (内含: " + String(gift.内容).substring(0,20) + (String(gift.内容).length > 20 ? '...' : '') + ")" : gift.名称;
            const btn = document.createElement('button');
            btn.textContent = buttonText;
            btn.disabled = buttonDisabled;
            btn.onclick = () => handleAction('claim_gift', gift.名称, gift);
            const nameSpan = document.createElement('span'); nameSpan.className = "item-name"; nameSpan.title = gift.内容 || gift.名称; nameSpan.textContent = displayName;
            const detailSpan = document.createElement('span'); detailSpan.className = "item-detail"; detailSpan.style.cssText = detailStyle; detailSpan.textContent = gift.状态 + conditionText;
            const actionSpan = document.createElement('span'); actionSpan.className = "item-action"; actionSpan.appendChild(btn);
            li.appendChild(nameSpan); li.appendChild(detailSpan); li.appendChild(actionSpan);
            listElem.appendChild(li);
        });
    }

    function populateSkills() {
        const listElem = document.getElementById('skillListElem');
        listElem.innerHTML = '';
        if (!parsedPanelData.技能列表 || parsedPanelData.技能列表.length === 0) {
            listElem.innerHTML = '<li><span class="item-name" style="text-align:center; display:block;">技能书一片空白...</span></li>'; return;
        }
        parsedPanelData.技能列表.forEach(skill => {
            const li = document.createElement('li');
            const nameSpan = document.createElement('span'); nameSpan.className = "item-name"; nameSpan.textContent = skill.名称;
            const detailSpan = document.createElement('span'); detailSpan.className = "item-detail"; if(skill.详情颜色) detailSpan.style.color = skill.详情颜色; detailSpan.textContent = skill.详情;
            const actionSpan = document.createElement('span'); actionSpan.className = "item-action";
            if(skill.按钮文字) {
                const btn = document.createElement('button');
                btn.textContent = skill.按钮文字 || '操作';
                btn.onclick = () => handleAction('manage_skill', skill.名称, skill); // Pass the whole skill object
                actionSpan.appendChild(btn);
            }
