            listElem.innerHTML = '<li><span class="item-name" style="text-align:center; display:block;">暂无物品</span></li>'; return;
        }
        parsedPanelData.库存物品列表.forEach(item => {
            const li = document.createElement('li');
            const itemNameAndQuantity = item.名称 + " (x" + (item.数量 || 1) + ")";
            const nameSpan = document.createElement('span'); nameSpan.className = "item-name"; nameSpan.title = item.描述 || ''; nameSpan.textContent = itemNameAndQuantity;
            const detailSpan = document.createElement('span'); detailSpan.className = "item-detail"; detailSpan.textContent = item.描述 || '暂无描述';

            const useButton = document.createElement('button');
            useButton.textContent = '使用';
            useButton.onclick = () => handleAction('use_item', item.名称, item);
            const actionSpan = document.createElement('span'); actionSpan.className = "item-action";
            actionSpan.appendChild(useButton);

            li.appendChild(nameSpan); li.appendChild(detailSpan); li.appendChild(actionSpan);
            listElem.appendChild(li);
