    function populateFunctions() {
        const listElem = document.getElementById('functionListElem');
        listElem.innerHTML = '';
        if(!parsedPanelData.辅助功能列表 || parsedPanelData.辅助功能列表.length === 0) {
            listElem.innerHTML = '<li><span class="item-name" style="text-align:center; display:block;">辅助模块接口维护中...</span></li>'; return;
