            const detailSpan = document.createElement('span'); detailSpan.className = "item-detail"; if(func.详情颜色) detailSpan.style.color = func.详情颜色; detailSpan.textContent = func.详情 || '';
            const actionSpan = document.createElement('span'); actionSpan.className = "item-action"; actionSpan.appendChild(btn);
