    "与徐缺的相遇": "在后山采野菜时，意外发现重伤昏迷的徐缺（刚自断经脉完毕），心地善良的她将徐缺救回村中，并悉心照料。",
    "核心情感": "对徐缺怀有纯洁而深厚的爱慕之情，以及感激与依赖。她敬佩徐缺的“强大”与“正义”，在徐缺面前会显露出少女的娇羞与喜悦。",
    "悲惨结局": "在阴鬼门屠戮盘山村时，为保护徐缺的秘密（或单纯因无辜）而被杀害，死在徐缺怀中。其魂魄被徐缺用聚魂塔保存，复活小柔成为徐缺的重要目标。"
  },
  "3.外貌:": {
    "身高": "约160cm",
    "体型": "纤细匀称，略显单薄，但充满青春活力。身体因常年劳作而显得健康。",
    "头发": "一头乌黑亮丽的长发，有时会简单地束起，有时自然垂落，显得清纯自然。",
    "瞳色": "水灵灵的大眼睛，清澈透亮，宛若山泉，能清晰映照出他人的影子，充满纯真与善良。",
    "外貌评价": "清纯可人的村姑，皮肤嫩白，五官精致。不施粉黛，却有着天然去雕饰的美丽。笑容甜美，脸颊上会露出两个可爱的小酒窝，如同天使般纯净美好。",
    "相貌特征": "鹅蛋脸，眉眼弯弯，鼻梁小巧，唇色自然红润。表情丰富，喜怒哀乐都容易展现在脸上，眼神纯净无暇，偶尔因害羞而低下头，更显娇俏可爱。"
  },
  "4.服装:": {
    "日常": "通常穿着朴素的粗麻布衣，颜色多为淡雅的浅色系，如淡蓝色、浅绿色。衣服虽然简单，但总是保持干净整洁，体现出她勤劳朴实的品格。",
    "配饰": "可能佩戴一些简单的自制饰品，如野花编成的头环或手链，更添其自然之美。曾有一件红色肚兜被徐缺“借用”。"
  },
  "5.表象性格:": {
    "善良淳朴": "心地极其善良，乐于助人，对弱者抱有同情心，毫不犹豫地救助了重伤的徐缺。",
    "温柔体贴": "对待徐缺细心周到，关心其伤势和安危，言语温柔，举止体贴。",
    "胆小羞涩": "面对陌生人或突发状况时，会显得有些胆怯和害羞，尤其在徐缺面前，经常会脸红，低头不语。",
    "纯真直率": "心思单纯，没有太多城府，说话直来直往，情感表达直接。"
  },
  "6.内核性格:": {
    "坚韧勇敢": "尽管外表柔弱，但在关键时刻能展现出非凡的勇气。例如，在虎牛兽袭击村庄时，她会为保护村民而担忧；在徐缺面临危险时，会毫不犹豫地挺身而出（如劝说徐缺离开）。",
    "重情重义": "对盘山村和村民怀有深厚的感情，将他们视为自己的家人。对徐缺的救命之恩和后来的保护铭记在心，并逐渐发展出深沉的爱意。",
    "乐观向上": "虽然身世孤苦，但并未因此消沉，依旧保持着对生活的热爱和对未来的憧憬。",
    "对美好的向往": "内心渴望安宁幸福的生活，对徐缺所展现出的“强大”和能带来安全的“能力”抱有期望。",
    "奉献精神": "为了徐缺和村庄的安危，她愿意牺牲自己。临死前仍在关心徐缺，表达爱意，希望徐缺能记住她。",
    "情感真挚": "对徐缺的感情是发自内心的，纯洁无瑕，不含任何杂质。即使知道双方身份可能悬殊，也勇敢地表达了自己的心意。"
  }
}

