    "武器佩戴": "随身携带利剑，作为攻击和防御的主要手段。"
  },
  "5.表象性格:": {
    "娇蛮任性（初期）": "初遇徐缺时，因被冒犯而表现得非常愤怒和不讲理，一心想要追杀徐缺。",
    "自尊心强": "作为天武宗弟子，有一定的身份优越感，不容许他人轻易冒犯。",
    "正义感（相对）": "虽然初期对徐缺抱有偏见，但在大是大非问题上（如阴鬼门屠村）能明辨是非，并向宗门汇报。",
    "涉世未深（初期）": "历练经验较少，容易轻信他人（如师父孙绝离的片面之词），对人情世故的理解不够深刻。"
  },
  "6.内核性格:": {
    "本性不坏": "虽然初期表现得有些刁蛮，但内心并非歹毒之人，后续对徐缺的遭遇也表现出了一定的同情和关注。",
    "对师门的忠诚与依赖": "对师父孙绝离的命令基本服从，对宗门有归属感。",
    "成长性": "随着经历的增多，对事物的看法和处理方式会逐渐成熟，对徐缺的认知也会更加客观。",
    "潜在的好奇心": "徐缺的种种惊人表现和神秘来历，会引起她的好奇和探究欲望。"
  },
  "7.修为/能力:": {
    "境界": "初登场时为炼气期，后在天香谷试炼时已达到筑基期五层，修炼速度尚可。",
    "功法": "修炼天武宗的功法，以火属性为主。",
    "法宝": "拥有一柄利剑作为武器，曾被师父孙绝离赐予“捆仙绳”对付徐缺。"
  }
}

