 <body>
  <!-- disable-default-loading -->
  <div class="container">
    <div class="b-point-display-container">
        <span class="b-point-label">装逼值:</span> <span id="bPointValue" class="b-point-value">[SysAI:当前装逼值数值]</span>
    </div>

    <div class="system-panel">
      <h1 class="system-title">最强装逼打脸系统</h1>

      <div class="main-info-grid">
        <div class="info-column" id="host-primary-info">
            <h3>宿主档案</h3>
            <p><span class="info-label">姓名:</span> <span id="hostName" class="value">[SysAI:徐缺姓名] ([SysAI:徐缺化名])</span></p>
            <p><span class="info-label">境界:</span> <span id="hostRealm" class="value highlight">[SysAI:徐缺境界]</span></p>
            <p><span class="info-label">称号:</span> <span id="hostTitle" class="value">[SysAI:徐缺称号信息]</span></p>
            <p><span class="info-label">职业:</span> <span id="hostJob" class="value">[SysAI:徐缺职业信息]</span></p>
        </div>
        <div class="info-column" id="host-status-bars">
            <h3>状态面板</h3>
            <div class="status-item">
                <span class="info-label">生命值:</span>
                <div class="progress-bar-container">
                    <div class="progress-bar health" id="healthBar">[SysAI:当前生命百分比]%</div>
                </div>
            </div>
            <div class="status-item">
                <span class="info-label">体力值:</span>
                <div class="progress-bar-container">
                    <div class="progress-bar stamina" id="staminaBar">[SysAI:当前体力百分比]%</div>
                </div>
            </div>
            <div class="status-item">
                <span class="info-label">欲望值:</span>
                <div class="progress-bar-container">
                    <div class="progress-bar desire" id="desireBar">[SysAI:当前欲望百分比]%</div>
                </div>
            </div>
            <div class="status-item">
                <span class="info-label">经验值:</span>
                <div class="progress-bar-container">
                    <div class="progress-bar exp" id="expBar">[SysAI:经验百分比]%</div>
                </div>
            </div>
        </div>
      </div>

      <div class="tabs">
        <button class="tab-button active" onclick="openTab(event, 'shop')">系统商城</button>
        <button class="tab-button" onclick="openTab(event, 'gifts')">礼包系统</button>
        <button class="tab-button" onclick="openTab(event, 'skills')">功法技能</button>
        <button class="tab-button" onclick="openTab(event, 'inventory')">系统空间</button>
        <button class="tab-button" onclick="openTab(event, 'functions')">辅助功能</button>
      </div>

      <div id="shop" class="tab-content active">
        <h2>系统商城</h2>
        <ul></ul>
        <p style="font-size:0.8em; color:#8892b0; margin-top:1rem;">[SysAI:打折提示]</p>
      </div>
      <div id="gifts" class="tab-content">
        <h2>礼包中心</h2>
        <ul></ul>
      </div>
      <div id="skills" class="tab-content">
        <h2>功法与技能</h2>
        <ul></ul>
      </div>
      <div id="inventory" class="tab-content">
        <h2>系统空间 (仓库)</h2>
        <p style="text-align:center; color:#a8b2d1; margin-top:2rem;">[SysAI:系统空间描述或物品列表]</p>
        <ul></ul>
      </div>
      <div id="functions" class="tab-content">
        <h2>系统辅助功能</h2>
        <ul></ul>
      </div>

      <div class="pending-actions-container">
        <h3>待处理操作 (<span id="pendingActionsCount">0</span> 条)</h3>
        <ul id="pendingActionsList" class="pending-actions-list"></ul>
        <div class="pending-actions-buttons">
            <button onclick="sendPendingActionsToInput()">执行选中操作</button>
            <button id="clearPendingActionsBtn" onclick="clearPendingActions()">清除待选操作</button>
        </div>
      </div>

      <div class="footer-text-container">
        <p class="footer-text" id="systemSlogan">"[SysAI:系统标语]"</p>
      </div>
    </div>
  </div>

  <script>
    const SYSPANEL_AUX_CMD_VAR = "SYSPANEL_AUX_CMD"; // Variable name for AI commands
    const AUX_CMD_POLL_INTERVAL = 3000; // Poll every 3 seconds for AI commands
    let auxCmdPollTimer = null;

    let hostData = {
      name: "[SysAI:徐缺姓名]", alias: "[SysAI:徐缺化名]", realm: "[SysAI:徐缺境界]",
      title: "[SysAI:徐缺称号信息]", job: "[SysAI:徐缺职业信息]",

      // Percentages are directly from SysAI for bars
      healthPercent: String("[SysAI:当前生命百分比]").replace('%',''),
      staminaPercent: String("[SysAI:当前体力百分比]").replace('%',''),
      desirePercent: String("[SysAI:当前欲望百分比]").replace('%',''),
      expPercent: String("[SysAI:经验百分比]").replace('%',''),

      bPoint: parseInt(String("[SysAI:当前装逼值数值]").replace(/[^0-9]/g, '') || "0"),
      systemSlogan: "[SysAI:系统标语]",

      gifts: {
        mysteryGift: { name: "神秘大礼包", status: "可领取", claimed: false, contents: "经验丹x5, 初级强化石x10" },
        growthPack1: { name: "新手成长礼包", status: "已开启", claimed: true, contents: "大量经验, 功法残卷" }
      },
      skills: [
        { name: "逼王拳", detail: "评价：SSS级", action: "装备中"},
        { name: "佛怒火莲", detail: "评价：天阶", action: "查看"}
      ],
      shopItems: [
        { name: "小聚气丹丹方", price: 10, action: "兑换" },
        { name: "三千雷动身法", price: 1000, action: "兑换" }
      ],
      inventoryItems: [
        { name: "新手铁剑", quantity: 1, description: "基础武器。" },
        { name: "疗伤丹", quantity: 3, description: "回复少量生命。" }
      ],
      auxFunctions: [
        // Initial functions can be empty or have defaults.
        // AI will populate this via SYSPANEL_AUX_CMD_VAR
        // Example: { id: "aux_sys_upgrade", name: "系统升级", detail: "当前版本V1.5.0", action: "检查更新", disabled: true },
      ]
    };
    let pendingActions = [];

    function consoleLog(message) {
        console.log(`[SysPanel v1.5.0]: ${message}`);
    }

    function updatePendingActionsDisplay() {
        const listElement = document.getElementById('pendingActionsList');
        const countElement = document.getElementById('pendingActionsCount');
        if (!listElement || !countElement) return;
        countElement.textContent = pendingActions.length;
        listElement.innerHTML = '';
        pendingActions.forEach(actionText => {
            const listItem = document.createElement('li');
            listItem.textContent = actionText.length > 70 ? actionText.substring(0, 67) + "..." : actionText;
            listItem.title = actionText;
            listElement.appendChild(listItem);
        });
    }

    function addPendingAction(description) {
        pendingActions.push(description);
        updatePendingActionsDisplay();
        // Removed successful /echo for adding to pending list. Kept for critical errors only.
        consoleLog(`Action added to pending: ${description}`);
    }

    async function sendPendingActionsToInput() {
        if (pendingActions.length === 0) {
            consoleLog("No pending actions to send.");
            if (typeof triggerSlash === 'function') { // Still useful to notify user if they click with nothing to send
                triggerSlash(`/echo title=系统提示 severity=warning timeout=2000 "没有待处理的操作。" escapeHtml=false`);
            }
            return;
        }
        const combinedActionsText = pendingActions.join('\n');
        if (typeof triggerSlash === 'function') {
            try {
                await triggerSlash(`/setinput "${escapeForSetInput(combinedActionsText)}"`);
                consoleLog(`${pendingActions.length} actions prepared for user input.`);
                // Removed general success echo. User sees input filled.
                pendingActions = [];
                updatePendingActionsDisplay();
            } catch (e) {
                consoleLog(`ERROR filling combined actions to input: ${e.message || e}`);
                if (typeof triggerSlash === 'function') {
                     await triggerSlash(`/echo title=面板错误 severity=error timeout=3000 "填充操作到输入框失败！" escapeHtml=false`);
                }
            }
        } else {
            consoleLog(`WARN: triggerSlash not available for sendPendingActionsToInput.`);
        }
    }

    async function clearPendingActions() {
        if (pendingActions.length === 0 && typeof triggerSlash === 'function') {
            // triggerSlash(`/echo title=系统提示 severity=info timeout=1500 "待处理操作列表已为空。" escapeHtml=false`);
            // Reduced verbosity: no pop-up if already empty.
            consoleLog("Pending actions list already empty.");
            return;
        }
        pendingActions = [];
        updatePendingActionsDisplay();
        consoleLog("Pending actions cleared.");
        // No pop-up for clearing. It's a deliberate user action.
    }

    function updateProgressBar(barId, percentageText) {
        const barElement = document.getElementById(barId);
        if (!barElement) return;
        let cleanPercentage = parseFloat(String(percentageText).replace('%', ''));
        if (isNaN(cleanPercentage) || cleanPercentage < 0) cleanPercentage = 0;
        if (cleanPercentage > 100) cleanPercentage = 100;
        barElement.style.width = cleanPercentage + '%';
        barElement.textContent = cleanPercentage.toFixed(0) + '%';
    }

    async function initializePanel() {
        hostData.bPoint = parseInt(String(hostData.bPoint).replace(/[^0-9]/g, '') || "0");

        document.getElementById('hostName').textContent = `${hostData.name}${hostData.alias && hostData.alias !== hostData.name && hostData.alias !== "[SysAI:徐缺化名]" ? ' ('+hostData.alias+')' : ''}`;
        document.getElementById('hostRealm').textContent = hostData.realm;
        document.getElementById('hostTitle').textContent = hostData.title;
        document.getElementById('hostJob').textContent = hostData.job;

        updateProgressBar('healthBar', hostData.healthPercent);
        updateProgressBar('staminaBar', hostData.staminaPercent);
        updateProgressBar('desireBar', hostData.desirePercent);
        updateProgressBar('expBar', hostData.expPercent); //经验条只显示百分比

        document.getElementById('bPointValue').textContent = formatNumber(hostData.bPoint);
        const sloganEl = document.getElementById('systemSlogan');
        if (sloganEl) sloganEl.textContent = `"${hostData.systemSlogan || '装逼如风，常伴吾身！生死看淡，不服就干！'}"`;

        populateShop(); populateGifts(); populateSkills(); populateInventory(); populateFunctions();
        updatePendingActionsDisplay();
        const firstTabButton = document.querySelector('.tab-button.active');
        if (firstTabButton) { openTab({ currentTarget: firstTabButton }, firstTabButton.getAttribute('onclick').match(/'([^']+)'/)[1]);
        } else { const fallbackFirstTab = document.querySelector('.tab-button');
            if (fallbackFirstTab) { fallbackFirstTab.classList.add('active'); openTab({ currentTarget: fallbackFirstTab }, fallbackFirstTab.getAttribute('onclick').match(/'([^']+)'/)[1]); }
        }

        // Start polling for AI commands for aux functions
        if (typeof getVariables === 'function' && typeof triggerSlash === 'function') {
            if (auxCmdPollTimer) clearInterval(auxCmdPollTimer); // Clear existing if any
            auxCmdPollTimer = setInterval(checkForAuxFunctionUpdates, AUX_CMD_POLL_INTERVAL);
            consoleLog("Auxiliary function command polling started.");
        } else {
            consoleLog("WARN: getVariables or triggerSlash not available. AI cannot dynamically update aux functions.");
        }
    }
    function formatNumber(num) { return String(num).replace(/(\d)(?=(\d{3})+(?!\d))/g, '$1,'); }

    function populateShop() { /* Unchanged from v1.4.9, ensure no success popups */
        const shopList = document.getElementById('shop').querySelector('ul'); shopList.innerHTML = '';
        if (!hostData.shopItems || hostData.shopItems.length === 0) { shopList.innerHTML = '<li><span class="item-name" style="text-align:center; display:block;">万界商城通讯受阻...</span></li>'; return; }
        const discountActive = hostData.title && hostData.title.includes("装逼犯"); const discountRate = discountActive ? 0.9 : 1;
        hostData.shopItems.forEach(item => {
            const actualPrice = Math.floor(item.price * discountRate); let priceText = `${formatNumber(actualPrice)} 装逼值`;
            if (discountActive && item.price !== actualPrice) { priceText = `<span style="text-decoration: line-through; color: #8892b0;">${formatNumber(item.price)}</span> ${formatNumber(actualPrice)} 装逼值`; }
            const li = document.createElement('li');
            li.innerHTML = `<span class="item-name">${item.name}</span><span class="item-detail">${priceText}</span><span class="item-action"><button onclick="buyItem('${item.name.replace(/'/g, "\\'")}', ${actualPrice})">${item.action || '兑换'}</button></span>`;
            shopList.appendChild(li);
        });
        const discountP = document.getElementById('shop').querySelector('p'); if (discountP) { discountP.textContent = discountActive ? '* 系统检测到宿主“装逼犯”光环，商城商品自动九折优惠！' : '* 温馨提示：部分稀有商品可能需要特殊条件解锁。'; }
    }
    function populateGifts() { /* Unchanged from v1.4.9, ensure no success popups */
        const giftList = document.getElementById('gifts').querySelector('ul'); giftList.innerHTML = '';
        if (!hostData.gifts || Object.keys(hostData.gifts).length === 0) { giftList.innerHTML = '<li><span class="item-name" style="text-align:center; display:block;">暂无待开启的次元礼盒。</span></li>'; return; }
        for (const key in hostData.gifts) { const gift = hostData.gifts[key]; const li = document.createElement('li');
            let detailStyle = ''; if (gift.status === "可领取") detailStyle = 'color: #64ffda;'; else if (gift.status === "未解锁") detailStyle = 'color: #ff79c6;'; else if (gift.status === "已领取" || gift.status === "已开启") detailStyle = 'color: #4a5568;';
            let conditionText = gift.condition ? ` (${gift.condition})` : ''; let buttonText = '查阅'; let buttonDisabled = true;
            if (gift.status === "可领取" && !gift.claimed) { buttonText = '开启'; buttonDisabled = false; }
            else if (gift.status === "已领取" || gift.status === "已开启" || gift.claimed) { buttonText = '已开启'; buttonDisabled = true; }
            else if (gift.status === "未解锁") { buttonText = '未达到'; buttonDisabled = true; }
            const displayName = gift.contents ? `${gift.name} (内含: ${gift.contents.substring(0,20)}${gift.contents.length > 20 ? '...' : ''})` : gift.name;
            li.innerHTML = `<span class="item-name" title="${gift.contents || gift.name}">${displayName}</span><span class="item-detail" style="${detailStyle}">${gift.status}${conditionText}</span><span class="item-action"><button onclick="claimGift('${gift.name.replace(/'/g, "\\'")}')" ${buttonDisabled ? 'disabled' : ''}>${buttonText}</button></span>`;
            giftList.appendChild(li);
        }
    }
    function populateSkills() { /* Unchanged from v1.4.9, ensure no success popups */
        const skillList = document.getElementById('skills').querySelector('ul'); skillList.innerHTML = '';
        if (!hostData.skills || hostData.skills.length === 0) { skillList.innerHTML = '<li><span class="item-name" style="text-align:center; display:block;">技能书一片空白，待宿主顿悟。</span></li>'; return; }
        hostData.skills.forEach(skill => { const li = document.createElement('li');
            let detailHtml = `<span class="item-detail" ${skill.detailColor ? `style="color:${skill.detailColor}"` : ''}>${skill.detail}</span>`; let actionHtml = '';
            if (skill.action !== null) { actionHtml = `<span class="item-action"><button onclick="manageSkill('${skill.name.replace(/'/g, "\\'")}')">${skill.action}</button></span>`; }
            li.innerHTML = `<span class="item-name">${skill.name}</span> ${detailHtml} ${actionHtml}`; skillList.appendChild(li);
        });
    }
    function populateInventory() { /* Unchanged from v1.4.9 */
        const inventoryList = document.getElementById('inventory').querySelector('ul');
        const inventoryPlaceholder = document.getElementById('inventory').querySelector('p');
        inventoryList.innerHTML = '';
        if (!hostData.inventoryItems || hostData.inventoryItems.length === 0) {
            if (inventoryPlaceholder) inventoryPlaceholder.textContent = "系统空间空空如也...";
            inventoryList.innerHTML = '<li><span class="item-name" style="text-align:center; display:block;">暂无物品</span></li>';
            return;
        }
        if (inventoryPlaceholder) inventoryPlaceholder.style.display = 'none';
        hostData.inventoryItems.forEach(item => {
            const li = document.createElement('li');
            const itemNameAndQuantity = `${item.name} (x${item.quantity || 1})`;
            li.innerHTML = `<span class="item-name" title="${item.description || ''}">${itemNameAndQuantity}</span> <span class="item-detail">${item.description || '暂无描述'}</span>`;
            inventoryList.appendChild(li);
        });
    }
    function populateFunctions() { // This will now be dynamically updated by AI commands
        const funcList = document.getElementById('functions').querySelector('ul'); funcList.innerHTML = '';
        if(!hostData.auxFunctions || hostData.auxFunctions.length === 0) {
            funcList.innerHTML = '<li><span class="item-name" style="text-align:center; display:block;">系统模块接口维护中...或等待AI解锁新功能。</span></li>'; return;
        }
        hostData.auxFunctions.forEach(func => {
            const li = document.createElement('li');
            let detailHtml = `<span class="item-detail" ${func.detailColor ? `style="color:${func.detailColor}"` : ''}>${func.detail || ''}</span>`;
            let actionHtml = `<span class="item-action"><button onclick="useFunction('${func.id || func.name.replace(/'/g, "\\'")}', ${func.cost || 0})" ${func.disabled ? 'disabled' : ''}>${func.action || '启动'}</button></span>`;
            li.innerHTML = `<span class="item-name">${func.name}</span> ${detailHtml} ${actionHtml}`;
            funcList.appendChild(li);
        });
    }

    function openTab(evt, tabName) { /* Unchanged from v1.4.9 */
        let i, tabcontent, tablinks; tabcontent = document.getElementsByClassName("tab-content");
        for (i = 0; i < tabcontent.length; i++) { tabcontent[i].style.display = "none"; tabcontent[i].classList.remove("active"); }
        tablinks = document.getElementsByClassName("tab-button"); for (i = 0; i < tablinks.length; i++) { tablinks[i].classList.remove("active"); }
        const currentTabContent = document.getElementById(tabName); if (currentTabContent) { currentTabContent.style.display = "block"; currentTabContent.classList.add("active"); }
        if (evt && evt.currentTarget) { evt.currentTarget.classList.add("active");
        } else { const buttons = document.querySelectorAll('.tab-button'); buttons.forEach(button => { if (button.getAttribute('onclick').includes(`'${tabName}'`)) { button.classList.add('active'); } }); }
    }
    function escapeForSetInput(text) { /* Unchanged from v1.4.9 */
        if (typeof text !== 'string') text = String(text);
        return text.replace(/"/g, '\\"').replace(/'/g, "\\'");
    }

    async function buyItem(itemName, price) { /* Logic mostly same, remove success popups */
        if (hostData.bPoint >= price) {
            hostData.bPoint -= price;
            updateBPointDisplay();
            consoleLog(`Item bought: ${itemName}, cost: ${price}.`);
            const actionDescription = `我用${price}装逼值兑换了【${itemName}】。(剩余${formatNumber(hostData.bPoint)}装逼值)`;
            addPendingAction(actionDescription);
        } else {
            consoleLog(`ERROR: Insufficient B-Points to buy ${itemName}.`);
            if (typeof triggerSlash === 'function') {
                 try { await triggerSlash(`/echo title=兑换失败 severity=error timeout=3000 "装逼值不足 (${formatNumber(hostData.bPoint)}/${formatNumber(price)})，无法兑换【${itemName}】！" escapeHtml=false`); } catch(e) {/*ignore*/}
            }
        }
    }

    async function claimGift(giftName) { /* Logic mostly same, remove success popups */
        const giftKey = Object.keys(hostData.gifts).find(key => hostData.gifts[key] && hostData.gifts[key].name === giftName);
        if (giftKey && hostData.gifts[giftKey] && !hostData.gifts[giftKey].claimed && hostData.gifts[giftKey].status === "可领取") {
            hostData.gifts[giftKey].claimed = true;
            hostData.gifts[giftKey].status = "已开启";
            populateGifts();
            consoleLog(`Gift claimed: ${giftName}.`);
            const giftContentsDescription = hostData.gifts[giftKey].contents ? `获得了：${hostData.gifts[giftKey].contents}` : "内容待揭晓。";
            const actionDescription = `我开启了礼包【${giftName}】。${giftContentsDescription}`;
            addPendingAction(actionDescription);
        } else {
            consoleLog(`ERROR: Gift ${giftName} cannot be claimed.`);
             if (typeof triggerSlash === 'function') {
                 try { await triggerSlash(`/echo title=操作失败 severity=warning timeout=3000 "礼盒【${giftName}】当前无法开启！" escapeHtml=false`); } catch(e) {/*ignore*/}
            }
        }
    }

    async function manageSkill(skillName) { /* Logic mostly same, remove success popups */
        consoleLog(`Managing skill: ${skillName}.`);
        const actionDescription = `我正在查看/管理我的技能【${skillName}】。`;
        addPendingAction(actionDescription);
    }

    // Use funcId (which can be func.id or func.name if id is not present)
    async function useFunction(funcIdentifier, cost = 0) {
        const funcToUse = hostData.auxFunctions.find(f => (f.id === funcIdentifier) || (f.name === funcIdentifier && !f.id));
        if (!funcToUse) {
            consoleLog(`ERROR: Aux function with identifier '${funcIdentifier}' not found.`);
            if(typeof triggerSlash === 'function') {
                try { await triggerSlash(`/echo title=面板错误 severity=error timeout=3000 "尝试使用未知辅助功能！" escapeHtml=false`); } catch(e) {/* ignore */}
            }
            return;
        }

        if (cost > 0 && hostData.bPoint < cost) {
            consoleLog(`ERROR: Insufficient B-Points for aux function ${funcToUse.name}.`);
             if (typeof triggerSlash === 'function') {
                try { await triggerSlash(`/echo title=功能失败 severity=error timeout=3000 "装逼值不足 (${formatNumber(hostData.bPoint)}/${formatNumber(cost)})，无法启动【${funcToUse.name}】！" escapeHtml=false`); } catch(e) {/*ignore*/ }
            }
            return;
        }

        if (cost > 0) {
            hostData.bPoint -= cost;
            updateBPointDisplay();
        }
        consoleLog(`Aux function used: ${funcToUse.name}. Cost: ${cost}`);
        const actionDescription = `我使用了系统辅助功能【${funcToUse.name}】${cost > 0 ? `，消耗了 ${cost} 装逼值` : ''}。`;
        addPendingAction(actionDescription);
    }

    function updateBPointDisplay() {
        document.getElementById('bPointValue').textContent = formatNumber(hostData.bPoint);
    }

    // --- Dynamic Auxiliary Function Handling ---
    async function checkForAuxFunctionUpdates() {
        if (typeof getVariables !== 'function' || typeof triggerSlash !== 'function') return;
        try {
            const vars = await getVariables();
            const cmdString = vars[SYSPANEL_AUX_CMD_VAR];

            if (cmdString && typeof cmdString === 'string' && cmdString.trim() !== "") {
                consoleLog(`Received Aux Command: ${cmdString}`);
                let cmdProcessed = false;
                const parts = cmdString.split(/:(.+)/); // Split on the first colon only
                const cmdType = parts[0].toUpperCase();
                const jsonData = parts[1];

                if (jsonData) {
                    try {
                        const data = JSON.parse(jsonData);
                        if (cmdType === "ADD") {
                            if (data.name) { // ID is preferred for updates
                                const existingIndex = data.id ? hostData.auxFunctions.findIndex(f => f.id === data.id) : hostData.auxFunctions.findIndex(f => f.name === data.name);
                                if (existingIndex > -1) {
                                    hostData.auxFunctions[existingIndex] = { ...hostData.auxFunctions[existingIndex], ...data };
                                    consoleLog(`Aux function updated: ${data.name}`);
                                } else {
                                    hostData.auxFunctions.push(data); // Add id if not present from AI
                                    if (!data.id) data.id = "aux_" + Date.now() + "_" + Math.random().toString(36).substring(2,7);
                                    consoleLog(`Aux function added: ${data.name}`);
                                }
                                cmdProcessed = true;
                            }
                        } else if (cmdType === "REMOVE") {
                            if (data.id) {
                                hostData.auxFunctions = hostData.auxFunctions.filter(f => f.id !== data.id);
                                consoleLog(`Aux function removed by ID: ${data.id}`);
                                cmdProcessed = true;
                            } else if (data.name) {
                                hostData.auxFunctions = hostData.auxFunctions.filter(f => f.name !== data.name);
                                consoleLog(`Aux function removed by Name: ${data.name}`);
                                cmdProcessed = true;
                            }
                        } else if (cmdType === "CLEAR_ALL") {
                            hostData.auxFunctions = [];
                            consoleLog("All aux functions cleared.");
                            cmdProcessed = true;
                        }

                        if (cmdProcessed) {
                            populateFunctions(); // Re-render the list
                        } else {
                            consoleLog(`WARN: Unknown or malformed aux command type: ${cmdType}`);
                        }
                    } catch (e) {
                        consoleLog(`ERROR parsing aux command JSON: ${e.message} - Data: ${jsonData}`);
                    }
                } else {
                     consoleLog(`WARN: Malformed aux command string (no JSON data): ${cmdString}`);
                }
                // Clear the command variable in SillyTavern
                await triggerSlash(`/setvar ${SYSPANEL_AUX_CMD_VAR} ""`);
            }
        } catch (e) {
            consoleLog(`ERROR in checkForAuxFunctionUpdates: ${e.message || e}`);
             // Stop polling if a major error occurs to prevent spam
            if (auxCmdPollTimer) clearInterval(auxCmdPollTimer);
            auxCmdPollTimer = null;
            consoleLog("ERROR: Auxiliary function command polling stopped due to error.");
            if (typeof triggerSlash === 'function') {
                 try { await triggerSlash(`/echo title=面板内部错误 severity=error timeout=5000 "动态功能更新模块出现故障，已停止运行！请检查控制台。" escapeHtml=false`); } catch(e2) {/*ignore*/}
            }
        }
    }

    document.addEventListener('DOMContentLoaded', initializePanel);
  </script>
